import json,sys
a=json.load(open(sys.argv[1]));b=json.load(open(sys.argv[2]))
def walk(x,y,p):
    if isinstance(x,dict) and isinstance(y,dict):
        for k in sorted(set(x)|set(y)):
            if k not in x: print("+",p+"/"+k, json.dumps(y[k])[:300])
            elif k not in y: print("-",p+"/"+k, json.dumps(x[k])[:300])
            else: walk(x[k],y[k],p+"/"+k)
    elif x!=y: print("~",p, json.dumps(x)[:200],"->",json.dumps(y)[:200])
walk(a,b,"")
EOF
